# 批注数据：src/utils/sandbox/sandbox-adapter.ts
# slug = src_utils_sandbox_sandbox_adapter_ts
ANNOTATIONS = [
    (63, 'before', '''本地副本：把一条权限规则字符串（如 Bash(ls) ）解析成「工具名 + 规则内容」结构，避免与 permissions.ts / bashPermissions.ts 形成循环依赖。匹配不到括号形式就当成纯工具名。'''),
    (78, 'before', '''从权限规则里抽「前缀」：形如 Foo:* 的规则返回 Foo（星号前那段），用于「某类命令整体排除」场景；匹配不到就返回 null。'''),
    (99, 'before', '''把 Claude Code 专属的路径前缀翻译成沙箱运行时能懂的路径。约定：//path 表示「文件系统根下的绝对路径」（去掉一个斜杠）；/path 表示「相对设置文件目录」（拼上该来源的根目录）；~/、./、裸路径原样透传，留给沙箱运行时自己归一化。'''),
    (138, 'before', '''解析 sandbox.filesystem.* 里的路径（allowWrite / denyWrite 等）。这类设置用「标准路径语义」：/path 就是字面上的绝对路径（不是相对设置目录），~/ 展开到家目录，./ 或裸名相对设置目录，//path 作为遗留写法仍当绝对路径处理。#30067 的修复点：权限规则里 /path 是相对设置目录，但用户在 sandbox.filesystem.allowWrite 里写绝对路径时期望原样生效。'''),
    (152, 'before', '''判断「是否只放行受管沙箱域名」：当策略设置里 sandbox.network.allowManagedDomainsOnly 为 true 时生效。这是策略层才能定的硬约束。'''),
    (159, 'before', '''判断「是否只放行受管可读路径」：策略设置 sandbox.filesystem.allowManagedReadPathsOnly 为 true 时生效，用来收紧读取白名单。'''),
    (172, 'before', '''把 Claude Code 的合并设置翻译成沙箱运行时的 SandboxRuntimeConfig。这是连接「设置系统」与「沙箱运行时」的核心转换器：从 WebFetch 规则里抽域名（允许 / 拒绝），从 Edit / Read 规则里抽文件系统路径；始终把当前目录和 Claude 临时目录放进可写白名单；网络配置、文件系统配置、ripgrep 配置逐项映射出来。导出给测试用。'''),
    (235, 'after', '''安全硬约束：无论来源，始终把各设置的 settings.json 文件加进「拒绝写入」列表——防止沙箱内的进程改写设置文件从而逃逸沙箱。受管 drop-in 目录也同样封死。'''),
    (256, 'after', '''同样封死 .claude/skills 的写入：沙箱运行时的 getDangerousDirectories 只保护 .claude/commands 和 .claude/agents，没管 skills；但 skills 也是「自动发现、自动加载、拥有完整 Claude 能力」的等同权限，必须同样在 OS 层拦截。'''),
    (404, 'before', '''在沙箱命令执行后、Claude 未沙箱的 git 跑起来之前，删除 cwd 下被「种」出来的裸仓库文件（HEAD / objects / refs 等）。见上面的 SECURITY 注释：攻击者若植入这些文件再配合 core.fsmonitor，能在 Claude 的未沙箱 git 上逃逸。'''),
    (422, 'before', '''检测 cwd 是否处于 git worktree 并解析出主仓库路径，结果缓存整会话。worktree 的 .git 是个文件（内含 gitdir: ...），不是目录；读 .git 抛 EISDIR 或读不到就说明不是 worktree，返回 null。解析时专门匹配 /.git/worktrees/ 段，避免把 /home/user/.github-projects 这类路径误判成主仓库。'''),
    (451, 'before', '''（memoize）检查沙箱依赖是否齐全：把本地的 ripgrep 命令与参数交给底层管理器校验，返回 errors / warnings；errors 非空表示沙箱跑不起来。带记忆化。'''),
    (459, 'before', '''取「沙箱是否在设置里被启用」：读设置里的 sandbox.enabled，缺省 false。读取出错时按「不启用」处理并打调试日志。'''),
    (469, 'before', '''取 autoAllowBashIfSandboxed 开关：沙箱启用时是否自动放行 Bash 命令，缺省 true。'''),
    (474, 'before', '''取 allowUnsandboxedCommands 开关：是否允许「不进沙箱」的命令，缺省 true。'''),
    (479, 'before', '''判断「沙箱是否为强制要求」：仅在用户显式启用沙箱且 failIfUnavailable 为 true 时成立——意味着缺依赖也不能退回到无沙箱。'''),
    (491, 'before', '''（memoize）判断当前平台是否被沙箱支持：macOS、Linux、WSL2+ 支持，WSL1 不支持。'''),
    (505, 'before', '''判断当前平台是否在 enabledPlatforms 白名单里（一个未文档化的设置）。主要用于 NVIDIA 企业部署：他们想先只在 macOS 上开 autoAllowBashIfSandboxed，其余平台关掉沙箱。未设置时默认全部平台放行；空数组表示全关；读取出错时保守地按「放行」处理。'''),
    (532, 'before', '''综合判断「沙箱到底开不开」：先过平台支持、再过依赖检查、再过 enabledPlatforms 白名单，最后才看用户设置里的 sandbox.enabled。四关全过才返回 true。'''),
    (562, 'before', '''当「用户显式开了沙箱却跑不起来」时，返回一段人话解释原因（平台不支持 / 不在白名单 / 依赖缺失），否则返回 undefined。#34044 的修复：以前 isSandboxingEnabled 在缺依赖时静默返回 false，用户配置了 allowedDomains 却毫无效果，是个安全陷阱。只在启动时调一次，有原因就提示给用户。'''),
    (597, 'before', '''返回「在 Linux / WSL 上无法完整生效的 glob 路径」警告列表：bubblewrap 不支持 glob，所以 Edit / Read 规则里带星号问号方括号的路径会有问题（尾部 /** 除外）。只在沙箱启用且平台是 Linux / WSL 时检查。'''),
    (647, 'before', '''判断「沙箱设置是否被策略锁定」：只要 flagSettings 或 policySettings 里显式设过 sandbox 的 enabled / autoAllowBashIfSandboxed / allowUnsandboxedCommands 任一，本地设置改了也不会生效，就视为被锁。'''),
    (669, 'before', '''把沙箱相关设置写回本地设置：启用开关、autoAllowBash、allowUnsandboxed 三项是可选的，只更新传了的那些，其余沿用现有值。注意 memoize 缓存以设置对象为键，设置一变自动失效。'''),
    (696, 'before', '''取「不被沙箱的命令」列表：从设置读 sandbox.excludedCommands，缺省空数组。这些命令会绕过沙箱直接跑。'''),
    (704, 'before', '''用沙箱包裹一条命令：若沙箱启用，先确保初始化完成（等 initializationPromise，没初始化就报错），再转交底层管理器。可选指定 shell / 自定义配置 / 中止信号。'''),
    (730, 'before', '''初始化沙箱（默认开启日志监控）。若已在初始化或已初始化就复用同一个 promise；沙箱没启用就直接返回。会把 ask 回调包一层以强制 allowManagedDomainsOnly 策略——所有调用路径（REPL / print / SDK）都被覆盖。初始化前「同步」创建 promise 以防竞态；还订阅设置变化以动态刷新配置。'''),
    (798, 'before', '''立即用当前设置刷新沙箱配置：改完权限后调用它，避免「pending 请求带着过期配置溜过去」的竞态。沙箱没启用就直接返回。'''),
    (808, 'before', '''重置沙箱状态：清理设置订阅、清空 worktree / scrub 路径缓冲、清掉 memoize 缓存（依赖检查、平台、初始化 promise），最后转交底层重置。'''),
    (828, 'before', '''把一个命令加进「不沙箱」列表（Claude CLI 专属，写回本地设置）。若带了 Bash 类的权限建议，会从中抽出命令前缀（如从 npm run test:* 抽出 npm run test）作为模式；列表里没有才追加，返回最终用的模式字符串。'''),
    (880, 'before', '''对外暴露的沙箱管理器接口：把上面所有能力（初始化、平台判断、配置读写、包裹命令、清理等）收敛成一个契约，方便上层按接口调用而不依赖具体实现。'''),
    (927, 'before', '''SandboxManager 实体：用 Claude 专属实现覆盖 initialize / isSandboxingEnabled / setSandboxSettings 等，其余纯查询类（getFsReadConfig、getProxyPort …）直接转发给底层 BaseSandboxManager。cleanupAfterCommand 在底层清理之后额外跑一遍裸仓库文件清除。'''),
    (973, 'before', '''重新导出沙箱运行时里的类型，方便上层从本模块统一 import，不必直接依赖 @anthropic-ai/sandbox-runtime。'''),
    (985, 'before', '''再导出运行时里的 SandboxViolationStore 与 SandboxRuntimeConfigSchema（值 / 校验器），供调用方直接用。'''),
]
